package com.bank.flink.tj;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.logging.Logger;

// The versioned (temporal) table. Keeps per-currency version history and
// answers FOR SYSTEM_TIME AS OF: the version valid at a given timestamp.
class VersionedRateTable {
    private static final Logger log = Logger.getLogger(VersionedRateTable.class.getName());

    // currency -> sorted list of versions by validFrom
    private final Map<String, List<RateVersion>> history = new TreeMap<>();

    void addVersion(RateVersion v) {
        history.computeIfAbsent(v.getCurrency(), k -> new ArrayList<>()).add(v);
        history.get(v.getCurrency()).sort(Comparator.comparingLong(RateVersion::getValidFromMillis));
        log.fine(() -> "rate version " + v.getCurrency() + "=" + v.getRate()
                + " from " + v.getValidFromMillis());
    }

    // FOR SYSTEM_TIME AS OF asOf: latest version whose validFrom <= asOf.
    BigDecimal rateAsOf(String currency, long asOfMillis) {
        List<RateVersion> versions = history.get(currency);
        if (versions == null) return null;
        BigDecimal result = null;
        for (RateVersion v : versions) {
            if (v.getValidFromMillis() <= asOfMillis) {
                result = v.getRate();
            } else {
                break; // versions are sorted; later ones are in the future
            }
        }
        return result;
    }

    // Processing-time style: the latest version (ignores point-in-time).
    BigDecimal latestRate(String currency) {
        List<RateVersion> versions = history.get(currency);
        if (versions == null || versions.isEmpty()) return null;
        return versions.get(versions.size() - 1).getRate();
    }
}
