package com.bank.flink.tj;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.logging.Logger;

// Joins each transaction to the point-in-time correct rate and converts to INR.
class TemporalJoinEngine {
    private static final Logger log = Logger.getLogger(TemporalJoinEngine.class.getName());

    private final VersionedRateTable rates;

    TemporalJoinEngine(VersionedRateTable rates) {
        this.rates = rates;
    }

    void join(Transaction t) {
        // FOR SYSTEM_TIME AS OF t.event_time
        BigDecimal rate = rates.rateAsOf(t.getCurrency(), t.getEventTimeMillis());
        if (rate == null) {
            log.warning(() -> "No rate version for " + t.getCurrency()
                    + " as of " + t.getEventTimeMillis());
            return;
        }
        BigDecimal inr = t.getAmount().multiply(rate).setScale(2, RoundingMode.HALF_UP);
        log.info(() -> "TEMPORAL JOIN txn=" + t.getTxnId() + " " + t.getAmount() + " "
                + t.getCurrency() + " @t=" + t.getEventTimeMillis()
                + " -> rate=" + rate + " -> INR=" + inr);
    }
}
