package com.bank.flink.tj;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

// Runnable demo: USD->INR rate changes during the day; transactions get the
// rate valid at their event time (not the latest).
public class TemporalJoinDemo {
    private static final Logger log = Logger.getLogger(TemporalJoinDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFormatter(new TjLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        VersionedRateTable rates = new VersionedRateTable();
        // USD->INR: 83.00 from 09:00, 83.50 from 12:00, 84.00 from 15:00.
        rates.addVersion(new RateVersion("USD", new BigDecimal("83.00"), 9 * 3600_000L));
        rates.addVersion(new RateVersion("USD", new BigDecimal("83.50"), 12 * 3600_000L));
        rates.addVersion(new RateVersion("USD", new BigDecimal("84.00"), 15 * 3600_000L));

        TemporalJoinEngine engine = new TemporalJoinEngine(rates);

        // Transactions at 10:00, 13:00, 16:00 — each gets the rate valid THEN.
        engine.join(new Transaction("T1", "USD", new BigDecimal("1000"), 10 * 3600_000L));
        engine.join(new Transaction("T2", "USD", new BigDecimal("1000"), 13 * 3600_000L));
        engine.join(new Transaction("T3", "USD", new BigDecimal("1000"), 16 * 3600_000L));

        // Contrast: a late-arriving transaction stamped 10:00 STILL gets 83.00,
        // even though the latest rate is now 84.00 (point-in-time correctness).
        engine.join(new Transaction("T4-late", "USD", new BigDecimal("1000"), 10 * 3600_000L));
        log.info(() -> "Latest rate (NOT used by temporal join) = " + rates.latestRate("USD"));
    }
}

// ─── Would be in TjLogFormatter.java in a real project ───
class TjLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                record.getMessage());
    }
}
